/// One event streamed from the live-sync engine to Flutter.
///
/// The real MLS group id NEVER appears here — only the pseudonymous
/// `nostr_group_id` (Security Rule 4). The `Debug` impl is presence-only.
class FfiRelayEvent {
  /// Which kind of event this is.
  final FfiRelayEventKind kind;

  /// Pseudonymous `nostr_group_id` (Location / GroupUpdate).
  final Uint8List? nostrGroupId;

  /// Sender's hex Nostr public key (Location).
  final String? senderPubkey;

  /// Decrypted location content JSON (Location).
  final String? content;

  /// Source event `created_at` seconds (Location).
  final PlatformInt64? eventCreatedAtSecs;

  /// Raw `kind:1059` gift-wrap JSON (Welcome).
  ///
  /// The wrapper's `created_at` is deliberately NOT surfaced alongside it. Its
  /// only consumer was a sync-cursor advance, and a `#p`-routed gift wrap is
  /// authored by a throwaway ephemeral key that anyone who knows this user's
  /// published npub can mint — so that field was a remotely-chosen number
  /// wired straight into the persisted inbox REQ floor. The inbox cursor is
  /// advanced in haven-core now, from the inbox REQ's own local open time
  /// (`haven_core::relay::live_sync::anchor::InboxAnchor`).
  final String? giftWrapJson;

  /// Closed status reason (Status). `None` on the one Status event that
  /// carries [`Self::unrecoverable_nostr_group_id`] instead.
  final FfiSyncStatusReason? statusReason;

  /// The pseudonymous `nostr_group_id` of a circle MDK halted (Status): a
  /// refresh nudge, emitted when MDK announces the halt — at the transition
  /// and at each open. The state itself is `CircleEngineStateFfi::Unrecoverable`
  /// and `RecoveryCauseFfi::Unrecoverable`, read on every circle read; act on
  /// those, not on this.
  ///
  /// The halt is per-circle and outlasts waiting and retries — only joining a
  /// replacement Welcome (a re-invite) clears it — so a "reconnecting" banner
  /// is the wrong response to it.
  ///
  /// Deliberately NOT a [`FfiSyncStatusReason`]. Every reason in that enum is
  /// self-clearing and names no circle — a relay outage, a pause, one message
  /// that would not apply, an offline backlog convergence will drain — and
  /// spelling a terminal per-circle verdict the same way is how a user gets
  /// told to re-create a working circle. `status_reason` is `None` whenever
  /// this is `Some`, so the two can never be read as one event.
  final Uint8List? unrecoverableNostrGroupId;

  /// What a live drive's relays blamed on this device's clock (Status): the
  /// same evidence a bridge driver entry's outcome carries, never the
  /// relays' words. Like the verdict above, not a [`FfiSyncStatusReason`]:
  /// it says nothing about the connection. `status_reason` is `None` when
  /// this is `Some`.
  final DeviceClockComplaintFfi? clockRejected;

  const FfiRelayEvent({
    required this.kind,
    this.nostrGroupId,
    this.senderPubkey,
    this.content,
    this.eventCreatedAtSecs,
    this.giftWrapJson,
    this.statusReason,
    this.unrecoverableNostrGroupId,
    this.clockRejected,
  });

  @override
  int get hashCode =>
      kind.hashCode ^
      nostrGroupId.hashCode ^
      senderPubkey.hashCode ^
      content.hashCode ^
      eventCreatedAtSecs.hashCode ^
      giftWrapJson.hashCode ^
      statusReason.hashCode ^
      unrecoverableNostrGroupId.hashCode ^
      clockRejected.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is FfiRelayEvent &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          nostrGroupId == other.nostrGroupId &&
          senderPubkey == other.senderPubkey &&
          content == other.content &&
          eventCreatedAtSecs == other.eventCreatedAtSecs &&
          giftWrapJson == other.giftWrapJson &&
          statusReason == other.statusReason &&
          unrecoverableNostrGroupId == other.unrecoverableNostrGroupId &&
          clockRejected == other.clockRejected;
}

/// Discriminator for [`FfiRelayEvent`] (struct-of-discriminant, like
/// [`DecryptOutcomeFfi`], to avoid pulling Dart `freezed` into the bindings).
enum FfiRelayEventKind {
  /// A decrypted location.
  location,

  /// A group membership/epoch update.
  groupUpdate,

  /// A raw gift-wrapped invitation (`kind:1059`); the consumer unwraps it.
  welcome,

  /// A non-content status/lifecycle signal. Carries either a
  /// [`FfiSyncStatusReason`] or — for the one terminal per-circle verdict —
  /// [`FfiRelayEvent::unrecoverable_nostr_group_id`]. Never both.
  status,
}

/// Non-content lifecycle/status reason on the live stream. Closed enum — a raw
/// error string never crosses the FFI (Security Rule 8). Mirrors the core
/// `SyncStatusReason`.
enum FfiSyncStatusReason {
  /// Establishing relay connections.
  connecting,

  /// All required relays connected.
  connected,

  /// A relay dropped; re-establishing.
  reconnecting,

  /// A relay is disconnected.
  disconnected,

  /// An incoming group message could not be processed (no cursor advance).
  unprocessable,

  /// An inbox (gift-wrap) processing step failed.
  inboxError,

  /// A relay-level operation failed.
  relayError,

  /// A session was started.
  sessionStarted,

  /// A session was stopped.
  sessionStopped,

  /// The session resumed from background.
  backgroundResumed,

  /// The session is paused between background bursts: no standing REQ, no
  /// socket.
  ///
  /// A STATE, never a fault. A consumer must not stamp a "disconnected since"
  /// from it: a burst interval can be as long as the receive-silence
  /// threshold, so a health model fed this as an outage would confirm a relay
  /// fault on a deliberate pause.
  paused,

  /// The engine refused a group message for a local resource bound and
  /// recorded it for a refetch by id, which only the catch-up sweep performs:
  /// the consumer should run one.
  refetchOwed,
}

/// Outcome of [`force_release_live_session`].
///
/// Closed enum — no raw error string crosses the FFI (Security Rule 8), and it
/// carries no path, relay URL, or group id.
enum ForceReleaseOutcomeFfi {
  /// No live session was installed; nothing to release.
  noSession,

  /// The session was stopped and every supervisor task joined, so no task
  /// of the ENGINE holds an `Arc<CircleManager>`. A call still inside the
  /// stopped core — a start or a pause the stop tore down beside — keeps
  /// its manager until that call returns.
  ///
  /// This does NOT mean the guard is free. Other holders — most importantly a
  /// `CircleManagerFfi` handle in another isolate — are untouched by this call,
  /// and `LiveSessionGuard::acquire` remains the only authority on whether an
  /// open will succeed. A caller that reads this as "the retry will work" can
  /// loop forever, stopping the engine on every pass.
  drained,

  /// The session was stopped but a supervisor task was still running when the
  /// join budget elapsed. The caller MUST NOT infer that the guard is free.
  stopTimedOut,
}

