/// FFI mirror of [`haven_core::circle::LeavePlan`].
///
/// Struct shape (rather than tagged enum) avoids pulling in Dart `freezed`
/// for sealed classes while preserving all the information.
class LeavePlanFfi {
  /// Which branch of the state machine to execute.
  final LeavePlanKindFfi kind;

  /// Hex-encoded successor pubkey when `kind == AdminHandoff`, else `None`.
  final String? successorHex;

  const LeavePlanFfi({required this.kind, this.successorHex});

  @override
  int get hashCode => kind.hashCode ^ successorHex.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is LeavePlanFfi &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          successorHex == other.successorHex;
}

/// Discriminator for [`LeavePlanFfi`].
///
/// Drives the Flutter-side leave state machine. See the core
/// `LeavePlan` docs for the full flow per variant.
enum LeavePlanKindFfi {
  /// Caller is a non-admin — skip handoff/demotion, go to `propose_leave`.
  nonAdmin,

  /// Caller is the sole admin — must promote `successor_hex` before
  /// self-demoting and leaving.
  adminHandoff,

  /// Caller is one of multiple admins — skip promotion and go directly
  /// to `propose_self_demote` + `propose_leave`.
  adminDemote,

  /// Caller is the sole remaining member — call
  /// `abandon_circle_local_only` to wipe the local row.
  abandon,

  /// MDK has no record of the group — call `complete_leave` to wipe the
  /// orphaned local row.
  orphanLocalOnly,
}

/// Where a leave stands (FFI mirror of `haven_core::relay::fanout::LeaveStatus`).
enum LeaveStatusFfi {
  /// The proposal is recorded and driven; a peer commits it.
  proposed,

  /// Not proposed yet; nothing is shared with the circle meanwhile.
  pending,

  /// Left on this device.
  completed,

  /// No leave was asked for.
  notLeaving,

  /// A leave step is made only by the app in front of its user.
  foregroundOnly,

  /// Refused for good, the leave's intent ended: this device is an admin
  /// and must step down first.
  adminMustStepDown,

  /// Refused for good, the leave's intent ended: the circle is not on this
  /// device.
  circleNotFound,

  /// Input the engine still holds for the circle comes first; the intent
  /// stands and the next call carries on.
  engineHeld,
}

/// Where the live session stands ([`LiveSyncFfi::lifecycle`]).
enum LiveLifecycleFfi {
  /// No session is installed.
  noSession,

  /// A session is installed and no longer running: stopped, or its worker
  /// gone. A stop that answered `stillHolding` leaves one here.
  stopped,

  /// Started, and claimed for by nobody yet: it makes no commit.
  launched,

  /// Claimed for the foreground: the one lifecycle that makes commits.
  foreground,

  /// In a background burst: subscribed, making no commit.
  burst,

  /// Paused between bursts: no REQ and no socket.
  paused,
}

/// One folded engine [`haven_core::nostr::mls::types::LocationMessageResult`],
/// FFI-friendly. A single `kind:445` ingest can yield SEVERAL of these (an
/// engine `advance_convergence` may release buffered inbound after the outer
/// event), so a driven ingest's outcome carries a `Vec` of them
/// ([`IngestOutcomeFfi::replayed`]).
///
/// No result moves a sync cursor, and the caller may not move one from them:
/// the group cursor is raised only in haven-core, from the local instant an
/// observation window opened (`haven_core::relay::cursor`), never from an
/// event's `created_at`, which the sender chose. A buffered future-epoch event
/// is re-surfaced by the engine once the gap fills; the caller never needs to
/// re-fetch it.
class LocationMessageResultFfi {
  /// Which of the five outcomes this result is.
  final LocationMessageResultKindFfi kind;

  /// The decrypted location — `Some` only when `kind == Location` AND the
  /// inner content parsed as a `LocationMessage`. A successfully-decrypted
  /// but unparseable inner (e.g. a forward-incompatible payload) still yields
  /// `kind == Location` with `location == None` (decrypt succeeded).
  final DecryptedLocationFfi? location;

  /// The MLS group id (raw bytes) this result belongs to — the LOCAL circle
  /// handle (never published; Rule 4 keeps it off the wire). Present for
  /// every variant so the caller can refresh / join / block / withdraw the
  /// right circle.
  final Uint8List mlsGroupId;

  /// The MLS epoch the message was authenticated at — meaningful only for
  /// `kind == Location` (0 otherwise).
  final BigInt epoch;

  const LocationMessageResultFfi({
    required this.kind,
    this.location,
    required this.mlsGroupId,
    required this.epoch,
  });

  @override
  int get hashCode =>
      kind.hashCode ^ location.hashCode ^ mlsGroupId.hashCode ^ epoch.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is LocationMessageResultFfi &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          location == other.location &&
          mlsGroupId == other.mlsGroupId &&
          epoch == other.epoch;
}

/// Discriminator for [`LocationMessageResultFfi`].
///
/// Mirrors the five
/// [`haven_core::nostr::mls::types::LocationMessageResult`] variants 1:1
/// (Dark Matter taxonomy). Unlike the pre-migration outcome, stale / duplicate
/// / out-of-order handling is entirely engine-internal (the engine durably
/// buffers a future-epoch event and re-surfaces it once the gap fills), so
/// there is NO `Unprocessable` / `PreviouslyFailed` here. A struct-with-
/// discriminant shape (rather than a tagged Rust enum) follows the existing
/// [`LeavePlanFfi`] convention and avoids pulling Dart `freezed` into the
/// generated bindings.
enum LocationMessageResultKindFfi {
  /// A decrypted application (location) message.
  location,

  /// The local client joined a group via an accepted welcome.
  joined,

  /// A durable, MLS-authenticated change to group state (membership, admin,
  /// rename, retention) or an epoch advance the receiver should react to by
  /// refreshing the circle's roster.
  groupUpdate,

  /// A previously-surfaced result was withdrawn because branch selection
  /// superseded the commit that produced it — the caller must treat the
  /// earlier change as if it never happened.
  invalidated,

  /// The group entered the unrecoverable state; the UI MUST block
  /// send/mutate for it (Rule 8, blocked-group state).
  unrecoverable,
}

/// What the one send of a recorded location did (FFI mirror of
/// `haven_core::relay::fanout::LocationPublish`). A relay's own words never
/// cross: an `OK false` is [`Self::Refused`] whatever it said.
enum LocationPublishFfi {
  /// A relay acknowledged it.
  accepted,

  /// Every relay that answered refused it.
  refused,

  /// No relay could be reached.
  unreachable,

  /// Not sent: it had expired.
  expired,

  /// Not sent: a fresh seal would not be made for its circle now.
  superseded,

  /// Not sent: no record of it is stored.
  ended,

  /// Not sent by this call: a send of it is under way.
  inFlight,

  /// No relay took it, and a relay's `invalid:`, `blocked:` or unprefixed
  /// refusal blamed its timestamp (`clock_skew::classify_publish_outcome`): this
  /// device's clock runs fast, as the relays judged it.
  clockAhead,

  /// As [`Self::ClockAhead`]: the clock runs slow.
  clockBehind,

  /// As [`Self::ClockAhead`], with no direction, or with relays that
  /// disagreed on it.
  clockUnspecified,
}

/// Which kind of value a [`log_alias`] call is aliasing.
///
/// Mirrors [`haven_core::log_alias::LogAliasClass`]. The class is part of the
/// hashed input, so the same value aliased in two classes yields two unrelated
/// handles.
enum LogAliasClassFfi {
  /// A circle, keyed by its `nostr_group_id` as 64-char hex.
  circle,

  /// A member or peer, keyed by their Nostr public key (hex or `npub1…`).
  peer,

  /// A Nostr event, keyed by its hex id.
  event,

  /// A relay, keyed by its URL.
  relay,

  /// A published `KeyPackage`, keyed by its `d` slot.
  keyPackage,

  /// A relay subscription, keyed by its id.
  subscription,
}

/// Key package bundle for publishing (FFI-friendly).
