/// What the profile relays answered about the local user's OWN kind-0 on one
/// [`CircleManagerFfi::fetch_my_profile`] call.
///
/// No catch-all variant, for the reason [`ProfileSyncOutcomeFfi`] has none.
enum OwnProfileRelayAnswerFfi {
  /// Nothing settled it: a cache read, a fetch that was not due, or one that
  /// found no kind-0 while a relay had yet to answer.
  unanswered,

  /// A relay served the kind-0.
  published,

  /// EVERY relay answered, and none has one: no profile is published.
  absent,
}

/// A member's public Nostr profile (kind-0 metadata), FFI-friendly.
///
/// Carries the resolved display fields plus `has_picture` (whether picture BYTES
/// are cached locally) and `is_known` (a kind-0 was resolved — possibly a blank
/// `{}`). It deliberately has **no picture URL field**: URLs never cross the FFI
/// (plan D2); Flutter renders bytes fetched via
/// [`CircleManagerFfi::get_profile_thumbnail`] /
/// [`CircleManagerFfi::get_profile_picture`].
class ProfileMetadataFfi {
  /// Profile owner's Nostr public key (hex).
  final String pubkeyHex;

  /// The same key in NIP-19 bech32 (`npub1...`), computed at the boundary.
  final String npub;

  /// kind-0 `display_name` (NIP-24), if present.
  final String? displayName;

  /// kind-0 `name` (NIP-01), if present.
  final String? name;

  /// kind-0 `about`, if present.
  final String? about;

  /// Whether picture bytes are cached (a `profile_pictures` row exists).
  final bool hasPicture;

  /// Whether a kind-0 was resolved (`true` even for a deliberately blank `{}`).
  final bool isKnown;

  /// Unix seconds when this profile was last fetched (TTL base; `0` = never).
  final PlatformInt64 fetchedAt;

  /// What the relays answered on THIS call — only
  /// [`CircleManagerFfi::fetch_my_profile`] sets it. A cache read is always
  /// [`OwnProfileRelayAnswerFfi::Unanswered`].
  final OwnProfileRelayAnswerFfi relayAnswer;

  /// Hex SHA-256 of the cached picture bytes, or `None` when no CURRENT bytes
  /// are cached (always `None` whenever `has_picture` is false, so it can never
  /// key a decode of stale bytes).
  ///
  /// Flutter uses this as the avatar decode-cache key. Blossom URLs are
  /// content-addressed, so this changes exactly when the picture changes —
  /// which is what makes a member's new photo actually re-render.
  final String? pictureSha256Hex;

  const ProfileMetadataFfi({
    required this.pubkeyHex,
    required this.npub,
    this.displayName,
    this.name,
    this.about,
    required this.hasPicture,
    required this.isKnown,
    required this.fetchedAt,
    required this.relayAnswer,
    this.pictureSha256Hex,
  });

  @override
  int get hashCode =>
      pubkeyHex.hashCode ^
      npub.hashCode ^
      displayName.hashCode ^
      name.hashCode ^
      about.hashCode ^
      hasPicture.hashCode ^
      isKnown.hashCode ^
      fetchedAt.hashCode ^
      relayAnswer.hashCode ^
      pictureSha256Hex.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ProfileMetadataFfi &&
          runtimeType == other.runtimeType &&
          pubkeyHex == other.pubkeyHex &&
          npub == other.npub &&
          displayName == other.displayName &&
          name == other.name &&
          about == other.about &&
          hasPicture == other.hasPicture &&
          isKnown == other.isKnown &&
          fetchedAt == other.fetchedAt &&
          relayAnswer == other.relayAnswer &&
          pictureSha256Hex == other.pictureSha256Hex;
}

/// What the UI may honestly say about the own profile right now (FFI mirror of
/// [`ProfilePendingState`]).
///
/// Three independent facts rather than one enum: how they render is a UI
/// concern, and collapsing them here would decide it in Rust.
class ProfilePendingStateFfi {
  /// A save is not yet served by every pool relay.
  final bool pending;

  /// The persisted retry ladder permits another attempt now.
  final bool retryDue;

  /// Seconds until the next attempt is due: `Some` only when pending and
  /// not due. Relative, never an instant (Security Rule 15).
  final int? nextRetryInSecs;

