          pending == other.pending &&
          retryDue == other.retryDue &&
          nextRetryInSecs == other.nextRetryInSecs;
}

/// A reference to a stored profile picture (no bytes).
///
/// Flutter uses `pubkey_hex` to fetch the cached bytes and `sha256_hex` as a
/// decode-cache key; the picture URL never crosses the FFI (plan D2) — and at
/// the moment a picture is SAVED there is no URL yet anyway: the bytes are
/// staged locally and uploaded by the next sync.
class ProfilePictureRefFfi {
  /// Owner's Nostr public key (hex).
  final String pubkeyHex;

  /// Hex SHA-256 of the post-sanitization bytes. Blossom is
  /// content-addressed, so this is also the address the eventual upload
  /// resolves to.
  final String sha256Hex;

  const ProfilePictureRefFfi({
    required this.pubkeyHex,
    required this.sha256Hex,
  });

  @override
  int get hashCode => pubkeyHex.hashCode ^ sha256Hex.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ProfilePictureRefFfi &&
          runtimeType == other.runtimeType &&
          pubkeyHex == other.pubkeyHex &&
          sha256Hex == other.sha256Hex;
}

/// Health of the profile-plane relay pool, as **counts only**.
///
/// Deliberately carries no URLs. Dart needs exactly one thing — whether the
/// plane can still operate — and a URL list crossing the FFI would give the UI
/// (and any crash/analytics sink it feeds) a copy of which relays this install
/// resolves profiles from. That set is the profile plane; naming it in Dart
/// re-creates in the app layer the very pointer Haven refuses to publish.
class ProfilePoolStatusFfi {
  /// Distinct relays configured for the profile category (curated pool
  /// unioned with the user's own additions).
  final int configured;

  /// How many of those are excluded because they also carry this account's
  /// location-plane traffic (the append-only contamination ledger).
  final int excluded;

  /// Relays that survive exclusion and may serve kind-0 lookups.
  final int usable;

  /// `true` when too few survive to operate the plane. Profile lookups are
  /// then skipped entirely (fail-closed: the plane NEVER falls back onto a
  /// location relay), so the roster shows cached names only until the user
  /// adds an uncontaminated profile relay.
  final bool isUnderflow;

  const ProfilePoolStatusFfi({
    required this.configured,
    required this.excluded,
    required this.usable,
    required this.isUnderflow,
  });

  @override
  int get hashCode =>
      configured.hashCode ^
      excluded.hashCode ^
      usable.hashCode ^
      isUnderflow.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ProfilePoolStatusFfi &&
          runtimeType == other.runtimeType &&
          configured == other.configured &&
          excluded == other.excluded &&
          usable == other.usable &&
          isUnderflow == other.isUnderflow;
}

/// What one own-profile sync pass did (FFI mirror of [`ProfileSyncOutcome`]).
///
/// No catch-all variant, deliberately: a new core outcome must force Dart to
/// decide what it means rather than folding into "something went wrong".
enum ProfileSyncOutcomeFfi {
  /// Nothing needed sending: nothing was pending, the pool already serves
  /// what was, or there was nothing public to retract.
  nothingPending,

  /// A relay newly took the profile this pass.
  published,

  /// The staged picture could not be uploaded, and nothing else was pending.
  uploadFailed,

  /// No relay newly took the profile, or the retraction gate held it back.
  publishFailed,

  /// Too few uncontaminated profile relays remain to publish at all.
  poolUnderflow,
}

/// The result of one own-profile sync pass (FFI mirror of
/// [`ProfileSyncReport`]).
///
/// Scalar-only, so the derived `Debug` is safe to log: the moment a URL or an
/// identifier lands in this struct it needs a redacting impl like its siblings
/// above.
class ProfileSyncResultFfi {
  /// What the pass did.
  final ProfileSyncOutcomeFfi outcome;

  /// Whether a save is STILL not served by every pool relay after this
  /// pass — the honest answer even for [`ProfileSyncOutcomeFfi::Published`],
  /// because a relay that missed it (or an edit saved mid-flight) leaves
  /// work behind.
  final bool stillPending;

  const ProfileSyncResultFfi({
    required this.outcome,
    required this.stillPending,
  });

  @override
  int get hashCode => outcome.hashCode ^ stillPending.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ProfileSyncResultFfi &&
          runtimeType == other.runtimeType &&
          outcome == other.outcome &&
          stillPending == other.stillPending;
}

