  /// Event tags: `[["h", group_id], ["expiration", ts], ...]`.
  final List<List<String>> tags;

  /// Ciphertext (base64). ChaCha20-Poly1305 under the MLS-exporter-derived
  /// `marmot/group-event` key — NOT NIP-44, which has not been on the
  /// kind-445 path since the Dark Matter cutover.
  final String content;

  /// Schnorr signature (128 hex chars).
  final String sig;

  const SignedLocationEventFfi({
    required this.id,
    required this.pubkey,
    required this.createdAt,
    required this.kind,
    required this.tags,
    required this.content,
    required this.sig,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      pubkey.hashCode ^
      createdAt.hashCode ^
      kind.hashCode ^
      tags.hashCode ^
      content.hashCode ^
      sig.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SignedLocationEventFfi &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          pubkey == other.pubkey &&
          createdAt == other.createdAt &&
          kind == other.kind &&
          tags == other.tags &&
          content == other.content &&
          sig == other.sig;
}

/// Why an epoch-rotation repair was declined — FFI mirror of
/// `haven_core::circle::SkipReason`.
///
/// Fieldless by construction: a skip is surfaced to the UI and to logs, and no
/// variant may carry a group id, a pubkey or an epoch (Security Rules 4/6/8).
///
/// **The UI must not collapse them.** [`Self::EpochUnrecoverable`] is the one
/// terminal reason — offering a retry would be a loop that cannot succeed —
/// while every other variant means "try again shortly". Any member may
/// repair: the repair is a self-update, which needs no admin.
enum SkipReasonFfi {
  /// The engine's epoch state is not `Stable` but will settle on its own (a
  /// commit is staged, merging, or recovering). Retryable.
  epochNotStable,

  /// The engine has frozen this group at its last stable epoch and refuses
  /// further group state. NEVER clears by waiting — this member has to be
  /// added again (MDK repairs the circle in place), or the circle
  /// re-created.
  epochUnrecoverable,

  /// The group's epoch changed too recently for a ratchet to be exhausted.
  recentEpochChange,

  /// The circle produced an MLS-authenticated inbound group event too recently
  /// to rule out a peer committing at the same epoch.
  recentInboundTraffic,

  /// A stored proposal is still waiting for a commit, so a remaining member
  /// may auto-commit it at any moment.
  pendingProposal,

  /// This circle was already repaired inside the 24-hour rate limit.
  rotatedRecently,
}

/// What an M8-4 subscription-health tick did (FFI mirror of
/// [`haven_core::relay::live_sync::HealthAction`]).
///
/// Fieldless / payload-free — no url, id, or hex — so it is leak-free by
/// construction (Security Rule 4/6).
enum SubscriptionHealthActionFfi {
  /// No live engine session — the inert no-op that ships while the live-sync
  /// engine is off (`liveSyncEnabled == false`).
  engineOff,

  /// The engine is running and every relay is connected — nothing to do.
  healthy,

  /// A relay had dropped, or a REQ the session expects was missing from the
  /// pool, so the WHOLE session was re-anchored (pool reconnected, every
  /// subscription re-issued at its cursor).
  resubscribed,

  /// Delivery silence alone: every socket was up and every REQ registered, so
  /// only the `(relay, sub)` endpoints that had gone quiet were re-issued.
  ///
  /// Distinct from [`Self::Resubscribed`] because the two differ by orders of
  /// magnitude in cost, and because this one is EXPECTED on a device whose
  /// circles are simply idle — a consumer that folded it into `Resubscribed`
  /// would show a normal quiet device as repeatedly losing its relays.
  targetedReanchor,

  /// The session is PAUSED between background bursts: it holds no standing
  /// REQ and no socket, so there was nothing for this tick to heal.
  ///
  /// Proof of nothing, like [`Self::EngineOff`]: a consumer must not read it
  /// as "the receive plane is whole". The next burst re-issues every REQ at
  /// its persisted cursor, which is what a healer would have done anyway.
  paused,

  /// A relay had dropped, or a REQ the session expects was missing, and the
  /// tick was not told the app is in the foreground: NOTHING was
  /// re-anchored. The whole-session repair is the foreground's, and waits
  /// for a caller that can claim it.
  ///
  /// The opposite of proof: the tick saw a receive plane that is not whole
  /// and left it so. A consumer must never read it as healthy.
  awaitingForeground,
}

/// Presence-only result of an M8-4 subscription-health maintenance tick.
///
/// Counters + an action enum only — never a relay url, group id, or pubkey — so
/// it is leak-free (Security Rule 4/6). This is the shape the Dart
/// `MaintenanceScheduler` folds ticks into.
class SubscriptionHealthOutcomeFfi {
  /// What the tick did.
  final SubscriptionHealthActionFfi action;

  /// Relays in the engine pool at check time (`0` when engine off).
  final int relaysTotal;

  /// Relays still coming up at check time (`Initialized` / `Pending` /
  /// `Connecting`); `0` when engine off. Reported so a caller can tell "all
  /// healthy" from "some still connecting" — a transient state that never
  /// triggers a resubscribe.
  final int relaysStillConnecting;

  /// Relays found dropped at check time (`0` when engine off).
  final int relaysDisconnected;

  /// `(relay, subscription)` REQ pairs the active session expected to be live
  /// (`0` when engine off or no session has started).
  final int subscriptionsExpected;

  /// How many of those the relay pool still held. A shortfall against
  /// `subscriptions_expected` is a REQ a relay ended with `CLOSED` that
  /// nothing upstream will re-issue — the receive blackout the relay
  /// connection counters cannot see, because the socket stays up.
  final int subscriptionsLive;

  /// Group REQs, still present in the pool, that had delivered neither an
  /// event nor an `EOSE` within the delivery-silence window. The inbox is
  /// never counted (a quiet inbox is the normal state). This is what a
  /// [`SubscriptionHealthActionFfi::TargetedReanchor`] acted on.
  final int subscriptionsSilent;

  const SubscriptionHealthOutcomeFfi({
    required this.action,
    required this.relaysTotal,
    required this.relaysStillConnecting,
    required this.relaysDisconnected,
    required this.subscriptionsExpected,
    required this.subscriptionsLive,
    required this.subscriptionsSilent,
  });

  @override
  int get hashCode =>
      action.hashCode ^
      relaysTotal.hashCode ^
      relaysStillConnecting.hashCode ^
      relaysDisconnected.hashCode ^
      subscriptionsExpected.hashCode ^
      subscriptionsLive.hashCode ^
      subscriptionsSilent.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SubscriptionHealthOutcomeFfi &&
          runtimeType == other.runtimeType &&
          action == other.action &&
          relaysTotal == other.relaysTotal &&
          relaysStillConnecting == other.relaysStillConnecting &&
          relaysDisconnected == other.relaysDisconnected &&
          subscriptionsExpected == other.subscriptionsExpected &&
          subscriptionsLive == other.subscriptionsLive &&
          subscriptionsSilent == other.subscriptionsSilent;
}

/// A cached tile and its conditional-revalidation metadata, for Dart.
///
/// `bytes` is public map imagery (encrypted only at rest), so it is surfaced
/// directly. No coordinates are carried, and there is intentionally no `Debug`
/// impl that prints `bytes`.
class TileCacheEntryFfi {
  /// Raw tile bytes (PNG).
  final Uint8List bytes;

  /// HTTP freshness deadline in unix milliseconds.
  final PlatformInt64 staleAtMs;

  /// `Last-Modified` as unix milliseconds, if present.
  final PlatformInt64? lastModifiedMs;

  /// `ETag` value, if present.
  final String? etag;

  const TileCacheEntryFfi({
    required this.bytes,
    required this.staleAtMs,
    this.lastModifiedMs,
    this.etag,
  });

  @override
  int get hashCode =>
      bytes.hashCode ^
      staleAtMs.hashCode ^
      lastModifiedMs.hashCode ^
      etag.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TileCacheEntryFfi &&
          runtimeType == other.runtimeType &&
          bytes == other.bytes &&
          staleAtMs == other.staleAtMs &&
          lastModifiedMs == other.lastModifiedMs &&
          etag == other.etag;
}

/// One withdrawn change and what became of it.
class WithdrawnChangeFfi {
  /// The circle.
  final Uint8List mlsGroupId;

  /// What the change was.
  final WithdrawnKindFfi kind;

  /// What became of it.
  final WithdrawnOutcomeFfi outcome;

  const WithdrawnChangeFfi({
    required this.mlsGroupId,
    required this.kind,
    required this.outcome,
  });

  @override
  int get hashCode => mlsGroupId.hashCode ^ kind.hashCode ^ outcome.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WithdrawnChangeFfi &&
          runtimeType == other.runtimeType &&
          mlsGroupId == other.mlsGroupId &&
          kind == other.kind &&
          outcome == other.outcome;
}

/// What a change of this device's that branch selection withdrew was.
enum WithdrawnKindFfi {
  /// The circle's name or description.
  groupProfile,

  /// The relays, the admins or a disband.
  appComponents,

  /// A removal.
  removeMembers,

  /// An invite.
  invite,
}

/// What became of a withdrawn change. None of these is "made": the two that
/// are on their way say so in their names.
enum WithdrawnOutcomeFfi {
  /// Asked for again and staged under a record: awaiting its relays.
  reissuedAwaitingRelays,

  /// Asked for again and queued, not staged: a later advance makes it.
  queuedAgain,

  /// The winning change touched the same thing: the user asks again.
  conflict,

  /// What it asked for is already so.
  alreadySatisfied,

  /// An invite whose key packages are spent: invited again
  /// ([`RelayManagerFfi::reinvite_driven`]) or by the user.
  reinviteRequired,

  /// Given up: the user asks again.
  abandoned,

  /// This device is no longer in the circle.
  notMember,

  /// The circle is being left; it was taken back, not failed.
  retiredForLeave,
}
